<div class="scroll"><table><thead><tr><th>Employee</th><th>Workplace</th><th>Clock in</th><th>Clock out</th><th>Status</th>@if($correctable)<th>Correction</th>@endif</tr></thead><tbody>@forelse($rows as $a)<tr><td><div class="person-cell"><span class="avatar">{{mb_substr($a->employee,0,1)}}</span><strong>{{$a->employee}}</strong></div></td><td>{{$a->branch}}</td><td>{{Carbon\Carbon::parse($a->clock_in,'UTC')->tz($business->timezone)->format('d M, H:i')}}</td><td>{{$a->clock_out?Carbon\Carbon::parse($a->clock_out,'UTC')->tz($business->timezone)->format('d M, H:i'):'—'}}</td><td><span class="badge {{$a->clock_out?'neutral':''}}">{{$a->clock_out?'Complete':'Clocked in'}}</span></td>@if($correctable)<td><details><summary>Adjust record</summary><form method="post" action="{{url('/attendance/'.$a->id.'/correct')}}">@csrf<label>Clock in ({{$business->timezone}})</label><input name="clock_in" type="datetime-local" value="{{Carbon\Carbon::parse($a->clock_in,'UTC')->tz($business->timezone)->format('Y-m-d\TH:i')}}" required><label>Clock out (blank = active)</label><input name="clock_out" type="datetime-local" value="{{$a->clock_out?Carbon\Carbon::parse($a->clock_out,'UTC')->tz($business->timezone)->format('Y-m-d\TH:i'):''}}"><label>Reason for correction</label><input name="reason" minlength="5" maxlength="500" required><div class="form-actions"><button>Save correction</button></div></form></details></td>@endif</tr>@empty<tr><td colspan="{{$correctable?6:5}}"><div class="empty-state">@include('partials.icon',['name'=>'clock'])<h3>A clear start.</h3><p>Attendance will appear here when your team starts clocking in.</p></div></td></tr>@endforelse</tbody></table></div>
